/**
 * The contract `file-picker.tsx` (native) and `file-picker.web.tsx` implement.
 *
 * Its own module for the usual reason — Metro resolves `./file-picker` to the
 * `.web.tsx` file on web, so that file cannot import the shared pieces from
 * `./file-picker` without importing itself.
 */

/** One picked file: its decoded text and its name. */
export type PickedFile = { text: string; name: string };

type FilePickerCommonProps = {
  /**
   * e.g. `"application/json,.json"`. Advisory on the dialog, which lets the user
   * pick "All files", so the web half also applies it to what comes back — to a
   * pick and to a drop alike. A file that does not match is skipped, never read.
   */
  accept?: string | undefined;
  /**
   * Take several files per pick: the dialog allows a multi-select and a drop
   * keeps every file. Off, a pick is one file and a drop keeps the first one
   * `accept` allows.
   */
  multiple?: boolean | undefined;
  label: string;
  hint?: string | undefined;
};

/**
 * One of `onPick` and `onPickMany` is required, and both may be given.
 * `onPickMany` wins when it is there; `onPick` alone is called once per file, so
 * a caller that handles files one at a time needs nothing new to take several.
 */
type FilePickerCallbacks =
  | {
      /**
       * Handed the picked file's decoded text, never the `File` object itself.
       * `File` is DOM-only, so a contract carrying one could not be implemented on
       * native — and the calling screen only ever wants the text anyway. With
       * `multiple` and no `onPickMany`, called once per file, in pick order.
       */
      onPick: (text: string, fileName: string) => void;
      /**
       * Called once per pick with every file in it, in pick order — one file
       * without `multiple`. Given, `onPick` is not called at all.
       */
      onPickMany?: ((files: PickedFile[]) => void) | undefined;
    }
  | {
      onPick?: ((text: string, fileName: string) => void) | undefined;
      onPickMany: (files: PickedFile[]) => void;
    };

export type FilePickerProps = FilePickerCommonProps & FilePickerCallbacks;

/**
 * Whether `file` is one `accept` allows, by the rules the `<input accept>`
 * attribute uses: `.ext` matches the name's ending, `type/*` the MIME type's
 * first half, and anything else the whole MIME type — all ignoring case. An
 * empty or absent `accept` allows everything.
 *
 * Here rather than in the web half so the rule has one home. It takes a name
 * and a type rather than a `File`, which native does not have.
 */
export function acceptsFile(accept: string | undefined, file: { name: string; type: string }) {
  const tokens = (accept ?? "")
    .split(",")
    .map((token) => token.trim().toLowerCase())
    .filter(Boolean);
  if (tokens.length === 0) return true;
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return tokens.some((token) => {
    if (token.startsWith(".")) return name.endsWith(token);
    if (token.endsWith("/*")) return type.startsWith(token.slice(0, -1));
    return type === token;
  });
}

/**
 * The native file picker — a placeholder, not an implementation.
 *
 * **This half does not pick a file.** Reading one off web needs
 * `expo-document-picker` and a file-system read for the URI it returns, both of
 * which are app-level choices with their own permission flow — so rather than
 * ship a drop zone that silently opens nothing, this says so on screen and
 * neither `onPick` nor `onPickMany` is ever called. `multiple` and `accept` are
 * taken so a shared call site typechecks, and do nothing here; an implementation
 * would hand them to `expo-document-picker` as its `multiple` and `type`, and can
 * filter what comes back with `acceptsFile` the way the web half does. Replace
 * this file in your app once those are wired up; `file-picker-base.ts` is the
 * contract to implement, and
 * `file-picker.web.tsx` is a working reference for the shape.
 */
import { Text, View } from "react-native";
import type { FilePickerProps } from "@/components/ui/file-picker-base";
import { Upload } from "@/components/ui/icons";

export function FilePicker({ label }: FilePickerProps) {
  return (
    <View className="w-full flex-col items-center gap-2 rounded-xl border-2 border-dashed border-muted-foreground/25 px-6 py-12">
      <Upload className="h-8 w-8 text-muted-foreground" />
      <Text className="text-center text-sm font-medium text-foreground">{label}</Text>
      <Text className="text-center text-xs text-muted-foreground">
        Picking a file is only available on the web app.
      </Text>
    </View>
  );
}

/**
 * The web file picker: a drop zone over a hidden `<input type="file">`.
 *
 * Both are DOM-only, which is why this is a `.web.tsx`. The caller never sees a
 * `File` — it gets the decoded text — so the calling screen stays shared.
 */
import { useRef, useState } from "react";
import { Text } from "react-native";
import { acceptsFile, type FilePickerProps } from "@/components/ui/file-picker-base";
import { Upload } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

export function FilePicker({ onPick, onPickMany, accept, multiple, label, hint }: FilePickerProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);

  async function take(list: FileList | null | undefined) {
    // Copied before the first `await`: the input's `FileList` is emptied when its
    // value is reset, and a drop's is gone once the event returns. `accept` is
    // only advisory on the dialog and not applied to a drop at all, so it is
    // applied here, to both.
    const allowed = Array.from(list ?? []).filter((file) => acceptsFile(accept, file));
    const files = multiple ? allowed : allowed.slice(0, 1);
    if (files.length === 0) return;
    const picked = await Promise.all(
      files.map(async (file) => ({ text: await file.text(), name: file.name })),
    );
    if (onPickMany) onPickMany(picked);
    else for (const file of picked) onPick?.(file.text, file.name);
  }

  return (
    <>
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        onDragOver={(e) => {
          e.preventDefault();
          setDragging(true);
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(e) => {
          e.preventDefault();
          setDragging(false);
          void take(e.dataTransfer.files);
        }}
        className={cn(
          "flex w-full flex-col items-center gap-2 rounded-xl border-2 border-dashed px-6 py-12 text-center transition-colors",
          dragging
            ? "border-primary bg-primary/5"
            : "border-muted-foreground/25 hover:border-muted-foreground/50",
        )}
      >
        <Upload className="h-8 w-8 text-muted-foreground" />
        <Text className="font-medium text-sm">{label}</Text>
        {hint ? <Text className="text-xs text-muted-foreground">{hint}</Text> : null}
      </button>
      <input
        ref={inputRef}
        type="file"
        {...(accept ? { accept } : {})}
        {...(multiple ? { multiple: true } : {})}
        className="hidden"
        onChange={(e) => {
          void take(e.target.files);
          // Allow re-selecting the same file after a reset.
          e.target.value = "";
        }}
      />
    </>
  );
}
